CREATE TABLE order_mail (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, kind VARCHAR(24) NOT NULL, dedupe_key VARCHAR(120) NOT NULL, payload_ciphertext TEXT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), locked_at DATETIME(6) NULL, last_error TEXT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY order_mail_dedupe_uq (dedupe_key), KEY order_mail_queue_idx (status,next_attempt_at), CONSTRAINT order_mail_kind_ck CHECK (kind IN ('buyer_received','owner_new_order','buyer_confirmed','buyer_cancelled')), CONSTRAINT order_mail_status_ck CHECK (status IN ('pending','processing','sent','failed','cancelled')), CONSTRAINT order_mail_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT order_mail_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci